"""The EMERGENCE adapter: the pack (regenerated byte for byte, accepted by the pinned loader, the brief's content),
the record mapping of section 3.3, the world counts of section 3.1 at every size, and the 200-user world through the
shipped pipeline and detection (the candidates, the fixed queries, nothing crossing a Boundary holds a record).

No assertion message here carries a record's text or ref: values are compared through digests, counts and labels.
"""
from __future__ import annotations

import contextlib
import io
import sqlite3
import statistics
import tempfile
import unittest
from collections import Counter
from pathlib import Path

from mycelic.collective.edge.egress import CANDIDATE_KEY_RE, check_artifact, read_log
from mycelic.collective.edge.weeks import iso_week, valid_week
from mycelic.collective.evaluate.baselines import closing_date, world_weeks
from mycelic.collective.jsonio import sha256_hex, strict_load
from mycelic.collective.packs import loader
from mycelic.collective.packs.connector import RECORD_KEYS, record_problems
from mycelic.collective.packs.loader import MIN_FIXTURES, PackError, load_pack_dir
from research.e2e_ingest import emergence_pack as ep
from research.e2e_ingest import emergence_world as ew
from research.mycelic.corpus import BACKGROUND_PREDICATES, CAUSAL_CHAINS, PRED_SURFACE, PREDICATES
from research.routing_spike import wire
from research.routing_spike.hq import Candidate
from research.routing_spike.site_process import SiteConfig, query_text
from research.routing_spike.world import candidate_label

ROOT = ew.ROOT
TEMPLATE_FOLLOWUPS = ROOT / "mycelic" / "collective" / "onboard" / "data" / "template" / "followups.json"


def _digest(values) -> str:
    return sha256_hex("\n".join(sorted(values)))


def _leak_hits(text: str, prefixes) -> dict[str, int]:
    return {"record_ref": len(ew.RECORD_REF_RE.findall(text)),
            "narrative_marker": len(ew.NARRATIVE_MARKER_RE.findall(text)),
            "narrative_prefix": sum(1 for p in prefixes if p in text)}


# --------------------------------------------------------------------------------------------------- the pack

class PackTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls) -> None:
        cls.corpus = ep.world_corpus()
        cls.pack = load_pack_dir(ew.PACK_DIR, expected_id=ew.PACK_ID)

    def test_the_committed_pack_is_the_regenerated_pack_byte_for_byte(self) -> None:
        result = ep.check_pack(ew.PACK_DIR, corpus=self.corpus)
        self.assertEqual(result["differing"], [])
        self.assertIsNone(result["loader_problem"])
        self.assertTrue(result["ok"])
        self.assertEqual(sorted(result["sha256"]), sorted(ep.FILE_NAMES))
        with tempfile.TemporaryDirectory() as tmp:
            ep.write_pack(tmp, corpus=self.corpus)
            fresh = ep.read_pack_bytes(tmp)
            committed = ep.read_pack_bytes(ew.PACK_DIR)
            self.assertEqual(sorted(fresh), sorted(committed))
            for name in ep.FILE_NAMES:
                self.assertEqual(sha256_hex(fresh[name]), sha256_hex(committed[name]), name)
        listed = sorted(p.relative_to(ew.PACK_DIR).as_posix() for p in ew.PACK_DIR.rglob("*") if p.is_file())
        self.assertEqual(listed, sorted(ep.FILE_NAMES))

    def test_the_loader_cli_check_accepts_the_pack(self) -> None:
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            code = loader.main(["check", str(ew.PACK_DIR)])
        self.assertEqual(code, 0)
        self.assertIn("pack: emergence 0.1.0", out.getvalue())
        self.assertEqual(self.pack.hashes(), ep.load_emergence_pack().hashes())

    def test_the_vocabulary_is_the_chains_and_revenue_miss_over_the_150_entities(self) -> None:
        pack = self.pack
        et = pack.entity_types[ew.ENTITY_TYPE]
        self.assertIsNone(et.id_format)
        self.assertTrue(et.egress)
        self.assertEqual(sorted(et.ids), sorted(ew.entity_ids(self.corpus)))
        self.assertEqual(len(et.ids), 150)
        self.assertTrue(all(i.startswith(ew.ID_PREFIX) and loader.ALIAS_ONLY_ID_RE.fullmatch(i) for i in et.ids))
        self.assertEqual(sorted(pack.predicates), sorted(ep.PACK_PREDICATES))
        for i, name in enumerate(ew.CHAIN_PREDICATES):
            expected = [ph for p in CAUSAL_CHAINS[i] if p != ew.REVENUE_MISS for ph in PRED_SURFACE[p]]
            self.assertEqual(list(pack.predicates[name].lexicon["en"]), expected, name)
        self.assertEqual(list(pack.predicates[ew.REVENUE_MISS].lexicon["en"]), PRED_SURFACE[ew.REVENUE_MISS])
        causal = [p for p in PREDICATES if p not in BACKGROUND_PREDICATES]
        covered = [ph for p in pack.predicates.values() for ph in p.lexicon["en"]]
        self.assertEqual(sorted(covered), sorted(ph for p in causal for ph in PRED_SURFACE[p]))
        self.assertEqual(len(covered), len(set(covered)))
        self.assertEqual(list(pack.negation["en"].post), ["not"])
        self.assertEqual(pack.negation_window, 8)
        self.assertEqual(pack.languages, ("en",))
        self.assertTrue(pack.illustrative and pack.same_author_as_code)
        self.assertIn("research/mycelic/corpus.py", pack.disclaimer)

    def test_egress_detectors_rules_questions_and_followups_are_the_briefs(self) -> None:
        pack = self.pack
        e = pack.egress
        self.assertEqual((e.k, e.suppress_below_days, e.count_granularity, e.close_lag_days, e.min_window_weeks),
                         (3, 31, "week", 14, 6))
        self.assertEqual(e.verdict_count_buckets, (3, 10, 50))
        self.assertEqual(e.egress_entity_types, (ew.ENTITY_TYPE,))
        self.assertTrue(e.require_master_data)
        self.assertEqual(sorted(e.never_fields), ["narrative", "reporter"])
        self.assertEqual(sorted(e.central_allowed_fields), ["codes", "entities.entity", "received_date", "site"])
        self.assertEqual((e.verify_max_records, e.question_budget_per_entity_per_day,
                          e.question_entities_per_site_per_day), (500, 5, 200))
        d = pack.detectors
        self.assertEqual((d["alert_budget_per_week"], d["cooldown_weeks"], d["baseline_weeks"], d["window_weeks"],
                          d["min_history_weeks"]), (20, 2, 8, 6, 6))
        self.assertEqual(d["decoy"]["stale_days"], 42)
        dq = strict_load((loader.BUILTIN_ROOT / "device_quality" / "detectors.json").read_bytes())
        mine = strict_load((ew.PACK_DIR / "detectors.json").read_bytes())
        for block in ("burst", "cooccurrence", "resolution", "independence", "decoy", "ranker"):
            self.assertEqual(mine[block], dq[block], block)
            self.assertEqual(sorted(d[block]), sorted(dq[block]), block)
        self.assertEqual(sorted(r.predicate for r in pack.rules.values()), sorted(ew.CHAIN_PREDICATES))
        for r in pack.rules.values():
            self.assertEqual((r.entity_type, r.min_sites, r.min_count_per_site, r.window_weeks),
                             (ew.ENTITY_TYPE, 2, 1, 8))
        self.assertEqual(sorted(pack.questions), [ep.TEMPLATE_ID])
        self.assertEqual(pack.questions[ep.TEMPLATE_ID].entity_types, (ew.ENTITY_TYPE,))
        self.assertIsNone(pack.questions[ep.TEMPLATE_ID].predicates)
        pd = pack.pushdown
        self.assertEqual((pd.min_confirming_sites, pd.min_independent_roots, pd.min_independent_reporters,
                          pd.freshness_days, pd.max_sibling_sites), (2, 3, 3, 42, 2))
        self.assertEqual(strict_load((ew.PACK_DIR / "followups.json").read_bytes()),
                         strict_load(TEMPLATE_FOLLOWUPS.read_bytes()))
        g = pack.generator
        self.assertEqual(g["start"], ew.START)
        self.assertEqual([s["id"] for s in g["sites"]], ew.site_ids(self.corpus.org))
        self.assertEqual(len(pack.fixtures), MIN_FIXTURES)
        self.assertEqual(len(pack.fixtures), ep.FIXTURE_RECORDS)
        refs = [f.record["record_ref"] for f in pack.fixtures]
        self.assertEqual(refs, [ew.record_ref(0, rid) for rid in range(MIN_FIXTURES)])

    def test_codes_are_one_placeholder_per_predicate_with_one_non_specific(self) -> None:
        codes = self.pack.codes
        self.assertEqual(sorted(codes), [f"EM-{i:02d}" for i in range(1, 9)])
        self.assertEqual(sorted(c.predicate for c in codes.values()), sorted(ep.PACK_PREDICATES))
        self.assertEqual([c.id for c in codes.values() if not c.specific], [ep.GENERIC_CODE])
        self.assertEqual(codes[ep.GENERIC_CODE].predicate, ew.REVENUE_MISS)
        self.assertEqual(self.pack.generator["codes"]["generic_code"], ep.GENERIC_CODE)
        for fixture in self.pack.fixtures:
            self.assertEqual(list(fixture.record["codes"]), [])

    def test_every_entity_name_is_an_alias_of_its_id_and_the_literal_table_is_refused(self) -> None:
        table = dict(self.pack.aliases[ew.ENTITY_TYPE])
        self.assertEqual(table, {name: ew.canonical_entity_id(name) for name in self.corpus.entities})
        self.assertEqual(len(table), 150)
        # the check can fail: the brief's wording (ids = the upper-cased names, alias name -> id) is an alias chain
        # for the pinned loader (``_aliases``: the target's folded form is an alias key), which is why the ids carry
        # the ``E-`` prefix
        files = ep.pack_files(self.corpus)
        plain = {name: name.upper() for name in self.corpus.entities}
        files["vocabulary.json"]["entity_types"][ew.ENTITY_TYPE]["ids"] = sorted(plain.values())
        files["aliases.json"] = {ew.ENTITY_TYPE: plain}
        files["generator.json"]["universe"][ew.ENTITY_TYPE] = sorted(plain.values())
        rename = {ew.canonical_entity_id(n): plain[n] for n in self.corpus.entities}
        for line in files[ep.FIXTURES_FILE]:
            line["record"]["entities"][ew.ENTITY_TYPE] = [rename[v] for v in line["record"]["entities"][ew.ENTITY_TYPE]]
            for g in line["gold"]:
                g["entity_id"] = rename[g["entity_id"]]
        with tempfile.TemporaryDirectory() as tmp:
            d = Path(tmp) / "emergence"
            (d / "fixtures").mkdir(parents=True)
            for name, data in ep.pack_bytes(files).items():
                (d / name).write_bytes(data)
            with self.assertRaises(PackError) as caught:
                load_pack_dir(d, expected_id=ew.PACK_ID)
        self.assertIn("alias chain", str(caught.exception))

    def test_no_pack_file_but_the_fixtures_holds_record_text_or_a_record_ref(self) -> None:
        prefixes = ew.narrative_prefixes(self.corpus)
        for name in ep.FILE_NAMES:
            if name == ep.FIXTURES_FILE:
                continue
            text = (ew.PACK_DIR / name).read_text(encoding="utf-8")
            self.assertEqual(_leak_hits(text, prefixes), {"record_ref": 0, "narrative_marker": 0,
                                                          "narrative_prefix": 0}, name)
        lines = (ew.PACK_DIR / ep.FIXTURES_FILE).read_bytes().split(b"\n")
        self.assertEqual(len([line for line in lines if line]), MIN_FIXTURES)


# --------------------------------------------------------------------------------------------------- the table

class WorldTableTests(unittest.TestCase):
    def test_the_generator_gives_section_3_1_at_every_size(self) -> None:
        for target in sorted(ew.WORLD_TABLE):
            with self.subTest(target_users=target):
                org, corpus, gold = ew.generate(target, 0)
                counts = ew.world_counts(org, corpus, gold)
                self.assertEqual(counts, dict(ew.WORLD_TABLE[target]))
                ew.check_world_counts(counts, target)
                self.assertEqual(len(ew.site_ids(org)), counts["sites"])
                self.assertEqual(sum(ew.records_per_site(corpus).values()), counts["records"])

    def test_a_world_missing_a_seed_invariant_count_is_refused(self) -> None:
        # the counts the generator derives from the size: one off means this is not the benchmark's world
        for key in ew.SEED_INVARIANT_COUNTS:
            with self.subTest(count=key):
                with self.assertRaises(ew.WorldError):
                    ew.check_world_counts({**ew.WORLD_TABLE[200], key: ew.WORLD_TABLE[200][key] - 1}, 200)
        with self.assertRaises(ew.WorldError):
            ew.check_world_counts(dict(ew.WORLD_TABLE[200]), 400)

    def test_a_structurally_impossible_world_is_refused(self) -> None:
        # the drawn counts are held to what the benchmark needs, not to seed 0's numbers
        row = dict(ew.WORLD_TABLE[200])
        for broken, why in (
            ({"sites": 1}, "one site cannot meet the two-site rule"),
            ({"teams": 6}, "fewer teams than sites"),
            ({"records": 239}, "too few records for 40 patterns at 2 sites x k=3"),
            ({"gold_rare": 41}, "more rare patterns than planted ones"),
        ):
            with self.subTest(**broken):
                with self.assertRaises(ew.WorldError, msg=why):
                    ew.check_world_counts({**row, **broken}, 200)
        self.assertEqual(ew.MIN_SITES * ew.ADMISSION_K * row["gold_discoverable"], 240,
                         "the record floor is the admission rule's own arithmetic")
        ew.check_world_counts({**row, "records": 240}, 200)
        for key in ew.SEED_DRAWN_COUNTS:
            with self.subTest(missing=key):
                with self.assertRaises(ew.WorldError):
                    ew.check_world_counts({k: v for k, v in row.items() if k != key}, 200)

    def test_every_development_seed_is_accepted_and_reports_its_draw(self) -> None:
        """The repair's point: the guard refused every seed but 0, so seeds 1-5 could only run as diagnostics.

        Seed 0 still matches section 3.1 exactly; the others differ only in counts the draw moves, and those
        differences are reported by ``table_row_diff`` rather than refused.
        """
        for seed in range(6):
            with self.subTest(seed=seed):
                org, corpus, gold = ew.generate(200, seed)
                counts = ew.world_counts(org, corpus, gold)
                ew.check_world_counts(counts, 200)
                diff = ew.table_row_diff(counts, 200)
                self.assertEqual(diff == [], seed == 0, "only seed 0 is section 3.1's own draw")
                for line in diff:
                    self.assertIn(line.split(":")[0], ew.SEED_DRAWN_COUNTS,
                                  "a seed-invariant count may never differ")


# --------------------------------------------------------------------------------------------------- the mapping

class RecordMappingTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls) -> None:
        cls.org, cls.corpus, cls.gold = ew.generate(200, 0)
        cls.pack = load_pack_dir(ew.PACK_DIR, expected_id=ew.PACK_ID)
        cls.records = ew.build_records(cls.corpus)
        cls.sites = ew.site_ids(cls.org)

    def test_every_record_has_exactly_the_connector_keys_and_passes_the_record_check(self) -> None:
        bad = []
        for rid, rec in enumerate(self.records):
            if tuple(sorted(rec)) != tuple(sorted(RECORD_KEYS)) or record_problems(rec, self.pack):
                bad.append(rid)
        self.assertEqual(bad, [])
        self.assertEqual(len(self.records), 12964)

    def test_the_mapping_is_section_3_3_field_by_field(self) -> None:
        corpus, org = self.corpus, self.org
        failures: list[str] = []
        for rid, rec in enumerate(self.records):
            r = corpus.recs[rid]
            uid = int(r["uid"])
            site = org.nodes[org.ancestor_at(uid, 3)].name.lower()
            checks = {
                "record_ref": rec["record_ref"] == f"em0-{rid:07d}",
                "site": rec["site"] == site,
                "received_date": rec["received_date"] == ew.received_date(int(r["t"])),
                "language": rec["language"] == "en",
                "codes": rec["codes"] == [],
                "entities": rec["entities"] == {"entity": [ew.ID_PREFIX + corpus.entities[int(r["anchor"])].upper()]},
                "narrative": rec["narrative"] == corpus.text(rid),
                "persons": rec["persons"] == {},
                "reporter": rec["reporter"] == f"u{uid}",
                "origin": rec["origin_ref"] is None and rec["origin_site"] is None,
                "synthetic": rec["synthetic"] is True,
            }
            failures += [f"{rid}:{name}" for name, ok in checks.items() if not ok]
        self.assertEqual(failures[:20], [])
        self.assertEqual(len(failures), 0)
        self.assertEqual(ew.received_date(0), "2024-01-01")
        self.assertEqual(ew.received_date(179), "2024-06-28")
        with self.assertRaises(ew.WorldError):
            ew.received_date(180)
        weeks = world_weeks(ew.START, ew.N_WEEKS)
        self.assertEqual((weeks[0], weeks[-1], len(weeks)), ("2024-W01", "2024-W26", 26))
        self.assertTrue(all(iso_week(ew.received_date(t)) in weeks for t in range(ew.N_DAYS)))

    def test_record_refs_are_unique_and_match_the_scan_pattern(self) -> None:
        refs = [r["record_ref"] for r in self.records]
        self.assertEqual(len(set(refs)), len(refs))
        self.assertTrue(all(ew.RECORD_REF_RE.fullmatch(ref) for ref in refs))
        self.assertTrue(all(ew.NARRATIVE_MARKER_RE.match(r["narrative"]) for r in self.records))

    def test_sites_are_the_org_site_nodes_lower_cased_with_the_briefs_per_site_counts(self) -> None:
        self.assertEqual(self.sites, [f"r{i:02d}-site-00" for i in range(7)])
        self.assertTrue(all(wire.SITE_ID_RE.fullmatch(s) for s in self.sites))
        per_site = ew.records_per_site(self.corpus)
        self.assertEqual(per_site, dict(Counter(r["site"] for r in self.records)))
        counts = sorted(per_site.values())
        self.assertEqual((counts[0], int(statistics.median(counts)), counts[-1]), (1458, 1805, 2574))
        self.assertEqual(sum(counts), 12964)

    def test_master_data_is_the_whole_entity_list_at_every_site(self) -> None:
        master = ew.master_data(self.corpus)
        ids = sorted(ew.entity_ids(self.corpus))
        self.assertEqual(sorted(master), self.sites)
        for sid in self.sites:
            self.assertEqual(master[sid], {"entity": ids})
        self.assertEqual(len(ids), 150)
        self.assertEqual(len(set(ids)), 150)
        self.assertTrue(all(loader.ALIAS_ONLY_ID_RE.fullmatch(i) for i in ids))
        for name in self.corpus.entities:
            self.assertEqual(ew.canonical_entity_id(name), "E-" + name.upper())

    def test_pack_predicate_maps_chains_revenue_miss_and_background(self) -> None:
        for i, chain in enumerate(CAUSAL_CHAINS):
            for p in chain:
                expected = ew.REVENUE_MISS if p == ew.REVENUE_MISS else ew.CHAIN_PREDICATES[i]
                self.assertEqual(ew.pack_predicate(p), expected, p)
        for p in BACKGROUND_PREDICATES:
            self.assertIsNone(ew.pack_predicate(p))
        self.assertEqual(len(ew.CHAIN_PREDICATES), 7)

    def test_gold_labels_follow_the_spikes_shape(self) -> None:
        labels = ew.gold_labels(self.corpus, self.gold)
        self.assertEqual(len(labels["patterns"]), 40)
        self.assertEqual(len(labels["decoys"]), 50)
        self.assertEqual(sum(1 for p in labels["patterns"] if p["rare"]), 18)
        self.assertEqual(sorted(Counter(d["class"] for d in labels["decoys"]).items()),
                         [(1, 10), (2, 10), (3, 10), (4, 10), (5, 10)])
        for p in labels["patterns"]:
            self.assertTrue(CANDIDATE_KEY_RE.fullmatch(p["key"]), p["id"])
            self.assertTrue(valid_week(p["found_from"]) and valid_week(p["found_to"]))
            self.assertLessEqual(p["found_from"], p["found_to"])
            self.assertTrue(p["sites"])
            self.assertTrue(set(p["sites"]) <= set(self.sites))
            self.assertIn(p["chain"], ew.CHAIN_PREDICATES)
            self.assertEqual(candidate_label(p["key"], p["found_from"], labels)["label"], "true")
            self.assertEqual(candidate_label(p["key"], p["found_to"], labels)["pattern"], p["id"])
        for d in labels["decoys"]:
            self.assertTrue(d["keys"])
            self.assertTrue(all(CANDIDATE_KEY_RE.fullmatch(k) for k in d["keys"]))
        self.assertEqual(candidate_label("entity:E-NOBODY:chain_supply", "2024-W10", labels)["label"], "background")
        # the keys of real patterns are each one (anchor, chain): anchors are drawn without replacement
        self.assertEqual(len({p["key"] for p in labels["patterns"]}), 40)


# --------------------------------------------------------------------------------------------------- the pipeline

class PipelineTests(unittest.TestCase):
    """The 200-user world for real: the shipped pipeline (M16) and detection, the candidates, the fixed queries."""

    @classmethod
    def setUpClass(cls) -> None:
        cls.tmp = tempfile.TemporaryDirectory()
        cls.world = ew.build_emergence_world(200, 0, Path(cls.tmp.name) / "w")

    @classmethod
    def tearDownClass(cls) -> None:
        cls.world.pipeline.close()
        cls.tmp.cleanup()

    def test_counts_as_of_and_weeks_are_the_briefs(self) -> None:
        w = self.world
        self.assertEqual(w.counts, dict(ew.WORLD_TABLE[200]))
        self.assertEqual(w.name, "emergence-200-seed-00")
        self.assertEqual(w.as_of, closing_date(w.pack, "2024-W26"))
        self.assertEqual(w.as_of, "2024-07-14")
        self.assertEqual((w.weeks[0], w.weeks[-1], len(w.weeks)), ("2024-W01", "2024-W26", 26))
        self.assertEqual(w.site_ids, [f"r{i:02d}-site-00" for i in range(7)])
        self.assertEqual(w.pack.id, ew.PACK_ID)
        self.assertEqual(Path(w.pack.directory), ew.PACK_DIR.resolve())
        self.assertTrue(w.planted)
        self.assertEqual(w.tie_salt, "e2e-ingest-v1")

    def test_every_site_store_holds_exactly_its_records_and_the_pipeline_raised_nothing(self) -> None:
        # M16: ingested is the store's own records (forwarded_in = 0), read mode=ro; duplicates and rejections are 0
        # because run_pipeline returned
        w = self.world
        total = 0
        for sid in w.site_ids:
            conn = sqlite3.connect(f"file:{w.workdir / 'edge' / f'site-{sid}.sqlite3'}?mode=ro", uri=True)
            try:
                refs = [r for (r,) in conn.execute("SELECT record_ref FROM records WHERE forwarded_in = 0 "
                                                   "ORDER BY record_ref").fetchall()]
                late = conn.execute("SELECT COUNT(*) FROM late_records").fetchone()[0]
                max_seq = conn.execute("SELECT MAX(seq) FROM records").fetchone()[0]
            finally:
                conn.close()
            expected = [r["record_ref"] for r in w.records if r["site"] == sid]
            with self.subTest(site=sid):
                self.assertEqual(len(refs), w.per_site_records[sid])
                self.assertEqual(_digest(refs), _digest(expected))
                self.assertEqual(late, 0)
                self.assertEqual(max_seq, len(refs))
            total += len(refs)
        self.assertEqual(total, w.counts["records"])
        self.assertEqual(total, 12964)

    def test_candidates_are_snapshot_candidates_in_score_order_the_first_60(self) -> None:
        w = self.world
        self.assertTrue(w.candidates)
        self.assertLessEqual(len(w.candidates), ew.TOP_N)
        self.assertGreaterEqual(w.detected, len(w.candidates))
        self.assertTrue(all(c["snapshot"] is not None for c in w.candidates))
        keys = [(-c["snapshot"]["score"], sha256_hex(f"{w.tie_salt}|{c['key']}")) for c in w.candidates]
        self.assertEqual(keys, sorted(keys))
        cands = [Candidate.from_detector(c) for c in w.candidates]
        ids = set(w.pack.entity_types[ew.ENTITY_TYPE].ids)
        for c in cands:
            self.assertEqual(c.entity_type, ew.ENTITY_TYPE)
            self.assertIn(c.entity_id, ids)
            self.assertIn(c.predicate, w.pack.predicates)
            self.assertTrue(valid_week(c.week) and valid_week(c.window_start))
            self.assertLessEqual(c.as_of, w.as_of)
        labels = Counter(candidate_label(c.key, c.week, w.labels)["label"] for c in cands)
        self.assertEqual(sum(labels.values()), len(cands))
        self.assertTrue(set(labels) <= {"true", "decoy", "background"})
        # M21: no evaluation window; every snapshot candidate of the run is listed
        self.assertEqual(len(ew.ordered_candidates({"candidates": w.candidates}, top_n=None)[0]), len(w.candidates))

    def test_the_fixed_questions_are_twenty_valid_questions_in_as_of_key_order(self) -> None:
        w = self.world
        qs = ew.fixed_questions(w, 20)
        self.assertEqual(len(qs), 20)
        self.assertEqual(len({q["question_id"] for q in qs}), 20)
        for q in qs:
            self.assertIsNone(check_artifact(w.pack, "", "question", q))
            self.assertEqual(q["pack_hash"], w.pack.config_hash)
            self.assertTrue(query_text(w.pack, q).startswith("In the last "))
        order = [(q["as_of"], q["candidate_key"]) for q in qs]
        self.assertEqual(order, sorted(order))
        cands = sorted((Candidate.from_detector(c) for c in w.candidates), key=lambda c: (c.as_of, c.key))
        self.assertEqual([(c.as_of, c.key) for c in cands[:20]], order)
        self.assertEqual([ew.question_for(w.pack, c) for c in cands[:20]], qs)

    def test_nothing_that_crossed_a_boundary_holds_a_record_ref_or_narrative(self) -> None:
        w = self.world
        prefixes = ew.narrative_prefixes(w.corpus)
        scanned = 0
        paths = [w.workdir / "hq" / "receive.jsonl"]
        paths += [w.workdir / "edge" / f"site-{s}.egress.jsonl" for s in w.site_ids]
        for path in paths:
            self.assertTrue(path.exists(), path.name)
            text = path.read_text(encoding="utf-8")
            scanned += len(text)
            self.assertEqual(_leak_hits(text, prefixes), {"record_ref": 0, "narrative_marker": 0,
                                                          "narrative_prefix": 0}, path.name)
        self.assertGreater(scanned, 0)
        rows = read_log(w.workdir / "hq" / "receive.jsonl")
        self.assertEqual({r["artifact_type"] for r in rows}, {"cells_bundle"})
        self.assertEqual(Counter(r["site"] for r in rows), {s: 26 for s in w.site_ids})

    def test_site_configs_name_the_pack_by_its_directory(self) -> None:
        w = self.world
        configs = ew.site_configs(w)
        self.assertEqual(sorted(configs), w.site_ids)
        for sid, cfg in configs.items():
            self.assertEqual(cfg.pack, w.pack.directory)
            self.assertEqual(cfg.site_id, sid)
            self.assertEqual((cfg.retrieval, cfg.max_records, cfg.embed_dim, cfg.demo_seed), ("tesseract", 50, 256, 0))
            self.assertEqual(cfg.clock_start, f"{w.as_of}T12:00:00Z")
            self.assertEqual(Path(cfg.graph_path), Path(cfg.edge_dir) / f"site-{sid}.graph.sqlite3")
            self.assertEqual(SiteConfig.from_json(cfg.to_json()).to_json(), cfg.to_json())
            self.assertEqual(sorted(cfg.master_data), [ew.ENTITY_TYPE])
            self.assertEqual(len(cfg.master_data[ew.ENTITY_TYPE]), 150)


